import{_ as c,a0 as l,w as d,s as p,I as r,x as o,a1 as t,A as i,ao as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"在 VirtualBox 中使用 Docker Machine 管理主機 | LCTT x X-CMD","titleTemplate":false,"description":"在 VirtualBox 中使用 Docker Machine 管理主機 | LCTT (201508) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 VirtualBox 中使用 Docker Machine 管理主機 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 VirtualBox 中使用 Docker Machine 管理主機 | LCTT (201508) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201508/20150527 Howto Manage Host Using Docker Machine in a VirtualBox","title":"在 VirtualBox 中使用 Docker Machine 管理主機","tag":"201508","desc":""},"relativePath":"201508/20150527 Howto Manage Host Using Docker Machine in a VirtualBox.md","filePath":"[post].md"}'),s={name:"201508/20150527 Howto Manage Host Using Docker Machine in a VirtualBox.md"};function k(u,e,h,m,x,D){const n=l("Link");return d(),p("div",null,[e[23]||(e[23]=r("h1",{id:"在-virtualbox-中使用-docker-machine-管理主機",tabindex:"-1"},[o("在 VirtualBox 中使用 Docker Machine 管理主機 "),r("a",{class:"header-anchor",href:"#在-virtualbox-中使用-docker-machine-管理主機","aria-label":"Permalink to “在 VirtualBox 中使用 Docker Machine 管理主機”"},"​")],-1)),e[24]||(e[24]=r("p",null,"大家好，今天我們學習在 VirtualBox 中使用 Docker Machine 來創建和管理 Docker 主機。Docker Machine 是一個可以幫助我們在電腦上、在雲端、在數據中心內創建 Docker 主機的應用。它為根據用户的配置和需求創建服務器並在其上安裝 Docker和客户端提供了一個輕鬆的解決方案。這個 API 可以用於在本地主機、或數據中心的虛擬機、或雲端的實例提供 Docker 服務。Docker Machine 支持 Windows、OSX 和 Linux，並且是以一個獨立的二進制文件包形式安裝的。仍然使用（與現有 Docker 工具）相同的接口，我們就可以充分利用已經提供 Docker 基礎框架的生態系統。只要一個命令，用户就能快速部署 Docker 容器。",-1)),e[25]||(e[25]=r("p",null,"本文列出一些簡單的步驟用 Docker Machine 來部署 docker 容器。",-1)),e[26]||(e[26]=r("h3",{id:"_1-安裝-docker-machine",tabindex:"-1"},[o("1. 安裝 Docker Machine "),r("a",{class:"header-anchor",href:"#_1-安裝-docker-machine","aria-label":"Permalink to “1. 安裝 Docker Machine”"},"​")],-1)),r("p",null,[e[1]||(e[1]=o("Docker Machine 完美支持所有 Linux 操作系統。首先我們需要從 ",-1)),t(n,{href:"https://github.com/docker/machine/releases"},{default:i(()=>[...e[0]||(e[0]=[o("github",-1)])]),_:1}),e[2]||(e[2]=o(" 下載最新版本的 Docker Machine，本文使用 curl 作為下載工具，Docker Machine 版本為 0.2.0。",-1))]),e[27]||(e[27]=a(`<p><strong>64 位操作系統</strong></p><pre><code># curl -L https://github.com/docker/machine/releases/download/v0.2.0/docker-machine_linux-amd64 &gt; /usr/local/bin/docker-machine
</code></pre><p><strong>32 位操作系統</strong></p><pre><code># curl -L https://github.com/docker/machine/releases/download/v0.2.0/docker-machine_linux-i386 &gt; /usr/local/bin/docker-machine
</code></pre><p>下載完成後，找到 <strong>/usr/local/bin</strong> 目錄下的 <strong>docker-machine</strong> 文件，讓其可以執行：</p><pre><code># chmod +x /usr/local/bin/docker-machine
</code></pre><p>確認是否成功安裝了 docker-machine，可以運行下面的命令，它會打印 Docker Machine 的版本信息：</p><pre><code># docker-machine -v
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/installing-docker-machine.png" alt="安裝 Docker Machine"></p><p>運行下面的命令，安裝 Docker 客户端，以便於在我們自己的電腦止運行 Docker 命令：</p><pre><code># curl -L https://get.docker.com/builds/linux/x86_64/docker-latest &gt; /usr/local/bin/docker
# chmod +x /usr/local/bin/docker
</code></pre><h3 id="_2-創建-virtualbox-虛擬機" tabindex="-1">2. 創建 VirtualBox 虛擬機 <a class="header-anchor" href="#_2-創建-virtualbox-虛擬機" aria-label="Permalink to “2. 創建 VirtualBox 虛擬機”">​</a></h3>`,12)),r("p",null,[e[4]||(e[4]=o("在 Linux 系統上安裝完 Docker Machine 後，接下來我們可以安裝 VirtualBox 虛擬機，運行下面的就可以了。",-1)),e[5]||(e[5]=r("code",null,"--driver virtualbox",-1)),e[6]||(e[6]=o(" 選項表示我們要在 VirtualBox 的虛擬機裏面部署 docker，最後的參數“linux” 是虛擬機的名稱。這個命令會下載 ",-1)),t(n,{href:"https://github.com/boot2docker/boot2docker"},{default:i(()=>[...e[3]||(e[3]=[o("boot2docker",-1)])]),_:1}),e[7]||(e[7]=o(" iso，它是個基於 Tiny Core Linux 的輕量級發行版，自帶 Docker 程序，然後 ",-1)),e[8]||(e[8]=r("code",null,"docker-machine",-1)),e[9]||(e[9]=o(" 命令會創建一個 VirtualBox 虛擬機（LCTT譯註：當然，我們也可以選擇其他的虛擬機軟件）來運行這個 boot2docker 系統。",-1))]),e[28]||(e[28]=a(`<pre><code># docker-machine create --driver virtualbox linux
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/creating-docker-machine.png" alt="創建 Docker Machine"></p><p>測試下有沒有成功運行 VirtualBox 和 Docker，運行命令：</p><pre><code># docker-machine ls
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/docker-machine-list.png" alt="Docker Machine List"></p><p>如果執行成功，我們可以看到在 ACTIVE 那列下面會出現一個星號“*”。</p><h3 id="_3-設置環境變量" tabindex="-1">3. 設置環境變量 <a class="header-anchor" href="#_3-設置環境變量" aria-label="Permalink to “3. 設置環境變量”">​</a></h3><p>現在我們需要讓 docker 與 docker-machine 通信，運行 <code>docker-machine env &lt;虛擬機名稱&gt;</code> 來實現這個目的。</p><pre><code># eval &quot;$(docker-machine env linux)&quot;
# docker ps
</code></pre><p>這個命令會設置 TLS 認證的環境變量，每次重啓機器或者重新打開一個會話都需要執行一下這個命令，我們可以看到它的輸出內容：</p><pre><code># docker-machine env linux

export DOCKER_TLS_VERIFY=1
export DOCKER_CERT_PATH=/Users/&lt;your username&gt;/.docker/machine/machines/dev
export DOCKER_HOST=tcp://192.168.99.100:2376
</code></pre><h3 id="_4-運行-docker-容器" tabindex="-1">4. 運行 Docker 容器 <a class="header-anchor" href="#_4-運行-docker-容器" aria-label="Permalink to “4. 運行 Docker 容器”">​</a></h3><p>完成配置後我們就可以在 VirtualBox 上運行 docker 容器了。測試一下，我們可以運行虛擬機 <code>docker run busybox</code> ，並在裏面裏執行 <code>echo hello world</code> 命令，我們可以看到容器的輸出信息。</p><pre><code># docker run busybox echo hello world
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/running-docker-container.png" alt="運行 Docker 容器"></p><h3 id="_5-拿到-docker-主機的-ip" tabindex="-1">5. 拿到 Docker 主機的 IP <a class="header-anchor" href="#_5-拿到-docker-主機的-ip" aria-label="Permalink to “5. 拿到 Docker 主機的 IP”">​</a></h3><p>我們可以執行下面的命令獲取運行 Docker 的主機的 IP 地址。我們可以看到在 Docker 主機的 IP 地址上的任何暴露出來的端口。</p><pre><code># docker-machine ip
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/docker-ip-address.png" alt="Docker IP 地址"></p><h3 id="_6-管理主機" tabindex="-1">6. 管理主機 <a class="header-anchor" href="#_6-管理主機" aria-label="Permalink to “6. 管理主機”">​</a></h3><p>現在我們可以隨心所欲地使用上述的 docker-machine 命令來不斷創建主機了。</p><p>當你使用完 docker 時，可以運行 <strong>docker-machine stop</strong> 來停止所有主機，如果想開啓所有主機，運行 <strong>docker-machine start</strong>。</p><pre><code># docker-machine stop
# docker-machine start
</code></pre><p>你也可以只停止或開啓一台主機：</p><pre><code>$ docker-machine stop linux
$ docker-machine start linux
</code></pre><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>最後，我們使用 Docker Machine 成功在 VirtualBox 上創建並管理一台 Docker 主機。Docker Machine 確實能讓用户快速地在不同的平台上部署 Docker 主機，就像我們這裏部署在 VirtualBox 上一樣。這個 virtualbox 驅動可以在本地機器上使用，也可以在數據中心的虛擬機上使用。Docker Machine 驅動除了支持本地的 VirtualBox 之外，還支持遠端的 Digital Ocean、AWS、Azure、VMware 以及其它基礎設施。</p><p>如果你有任何疑問，或者建議，請在評論欄中寫出來，我們會不斷改進我們的內容。謝謝，祝愉快。</p><hr>`,29)),r("p",null,[e[11]||(e[11]=o("via: ",-1)),t(n,{href:"http://linoxide.com/linux-how-to/host-virtualbox-docker-machine/"},{default:i(()=>[...e[10]||(e[10]=[o("http://linoxide.com/linux-how-to/host-virtualbox-docker-machine/",-1)])]),_:1})]),r("p",null,[e[15]||(e[15]=o("作者：",-1)),t(n,{href:"http://linoxide.com/author/arunp/"},{default:i(()=>[...e[12]||(e[12]=[o("Arun Pyasi",-1)])]),_:1}),e[16]||(e[16]=o(" 譯者：",-1)),t(n,{href:"https://github.com/bazz2"},{default:i(()=>[...e[13]||(e[13]=[o("bazz2",-1)])]),_:1}),e[17]||(e[17]=o(" 校對：",-1)),t(n,{href:"https://github.com/wxy"},{default:i(()=>[...e[14]||(e[14]=[o("wxy",-1)])]),_:1})]),r("p",null,[e[20]||(e[20]=o("本文由 ",-1)),t(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[18]||(e[18]=[o("LCTT",-1)])]),_:1}),e[21]||(e[21]=o(" 原創翻譯，",-1)),t(n,{href:"https://linux.cn/"},{default:i(()=>[...e[19]||(e[19]=[o("Linux中國",-1)])]),_:1}),e[22]||(e[22]=o(" 榮譽推出",-1))])])}const M=c(s,[["render",k]]);export{T as __pageData,M as default};
